/* MyAI 1.8.0 — Stage 2 mock hooks (additive; minified body above untouched):
 * a sample end-of-turn summary card in agent mode + the new bindings. */
;(function () {
  "use strict";
  var origEmit = window.runtime.EventsEmit;
  window.runtime.EventsEmit = function (name, data) {
    if (name === "chat:done" && data && !data.aborted && data.conversationId) {
      var agent = window.MyAIState && window.MyAIState.view && window.MyAIState.view.agentMode;
      if (agent) {
        setTimeout(function () {
          origEmit("chat:turn_summary", { summary: {
            conversationId: data.conversationId,
            turnId: 7,
            files: [
              { path: "src/agent.go", op: "modify", added: 12, removed: 3, changeId: "chg_demo1", protected: false },
              { path: "package.json", op: "modify", added: 2, removed: 0, changeId: "chg_demo2", protected: true }
            ],
            commands: [
              { command: "go test ./...", exitCode: 0, exitOk: true, verified: true, at: 1 },
              { command: "go build ./...", exitCode: 0, exitOk: true, verified: true, at: 2 }
            ],
            verification: { ran: true, ok: true, command: "go build ./..." },
            tokens: { prompt: 2140, completion: 620 },
            at: Math.floor(Date.now() / 1e3)
          } });
        }, 90);
      }
    }
    return origEmit(name, data);
  };
  var app = window.go && window.go.main && window.go.main.App;
  if (app) {
    var origView = app.SettingsView;
    app.SettingsView = async function () {
      var v = await origView();
      if (!v.editMode) v.editMode = "auto";
      if (!v.maxTurnTokens) v.maxTurnTokens = 2000000;
      return v;
    };
    app.SetEditMode = async function (m) {
      if (window.MyAIState && window.MyAIState.view) {
        window.MyAIState.view.editMode = m;
        window.MyAIState.view.confirmFileWrites = m === "review_each";
      }
      return null;
    };
    app.SetMaxTurnTokens = async function (v) {
      if (window.MyAIState && window.MyAIState.view) window.MyAIState.view.maxTurnTokens = v;
      return null;
    };
    app.GetTurnChanges = async function () { return []; };
    app.RevertTurnChanges = async function () { return { reverted: [], conflicts: [], errors: [] }; };
    // نقطه‌ی بازگشت پروژه (مرحله B) — داده‌ی نمونه برای دیدن مودال پیش‌نمایش
    app.PreviewCheckpointRestore = async function () {
      return {
        available: true,
        rewrite: ["src/agent.go", "package.json"],
        trash: ["dist/build.out"],
        unchanged: ["go.mod", "README.md"],
        skipped: [],
        error: ""
      };
    };
    app.RestoreCheckpoint = async function () {
      return {
        restored: ["src/agent.go", "package.json"],
        trashed: ["dist/build.out"],
        skipped: [],
        errors: [],
        trashDir: "C:\\\\Users\\\\User\\\\AppData\\\\Roaming\\\\MyAI\\\\trash\\\\demo"
      };
    };
  }
})();
